pose_description:
"Pose": {



"Tipo": "reclinado en el sofá, vista de ángulo alto",



"Cuerpo": "acostada de espaldas, el torso ligeramente diagonal sobre el sofá, las caderas giradas hacia la cámara",



"Torso": "suagamente arqueado, un brazo levantado detrás de la cabeza",



"Piernas": "ambas rodillas dobladas, piernas cruzadas en los muslos, pierna derecha sobre izquierda, pies hacia la parte inferior del marco",



"Brazos": {



"Derecha": "doblado, mano detrás de la cabeza / en el cabello",



"Izquierda": "doblada, mano también cerca de la cabeza / cabello"



}



"Cabeza": "se volvió ligeramente hacia la cámara, descansando en el cojín del respaldo del sofá",



"Expresión": "relajado, confiado, ojos en cámara"



}
